import { DetailArgs } from '@src/shared/dom';
import { FormContext, FormContextValue } from './context';
import { FormItemValue } from './types';
import { Consume, Provide } from '@src/framework/runtime-context';
import { ComponentInterface, Listen, State } from '@stencil/core';

export abstract class FormBaseComponent<T extends FormItemValue> implements ComponentInterface {
  connectedCallback?(): void;
  disconnectedCallback?(): void;

  /** Used to block subcomponents from getting the form context */
  @Provide({
    context: FormContext,
  })
  __contextBlocker: undefined;

  @Consume({
    context: FormContext,
    subscribe: true,
    path: ['_provider'],
  })
  _provider: FormContextValue<T>['_provider'];
  @Consume({
    context: FormContext,
    path: ['callbacks'],
  })
  callbacksFromContext?: FormContextValue<T>['callbacks'];
  @Consume({
    context: FormContext,
    subscribe: true,
    path: ['value'],
  })
  @State()
  valueFromContext?: FormContextValue<T>['value'];
  @Consume({
    context: FormContext,
    subscribe: true,
    path: ['status'],
  })
  @State()
  statusFromContext: FormContextValue<T>['status'];
  @Consume({
    context: FormContext,
    subscribe: true,
    path: ['disabled'],
  })
  @State()
  disabledFromContext: FormContextValue<T>['disabled'];

  @Listen('ksChange')
  onKsChangeForForm({ detail }: { detail: T | DetailArgs<[T, unknown]> }) {
    if (this._provider === 'formItem') {
      if ((detail as DetailArgs<[T]>)?._isDetailArgs) {
        const [value] = (detail || []) as DetailArgs<[T]>;
        this.callbacksFromContext?.onValueChange?.(value as T, []);
      } else {
        this.callbacksFromContext?.onValueChange?.(detail as T, []);
      }
    }
  }

  @Listen('ksBlur')
  onKsBlurForForm() {
    this.callbacksFromContext?.onBlur?.();
  }
}
